internal object DuaDoiDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("नया चनां दिक्खेआ", "ऐ अल्लाह, एह् चनां हम पर बरकतें, विश्वास, सुरक्षा ते इस्लाम दे कन्नै उगने देओ। (हे चनां,) मेरा रब ते तेरा रब अल्लाह ऐ।", "नया चनां देखने पर।", "हर नमें म्हीने आस्तै सुन्नत दुआ।"),
        "dua_janaza_adult" to DuaText("जनाज़ा प्रार्थना (वयस्क)", "ऐ अल्लाह, साडे जीवितें ते मरीनें गी, उंʼदे कन्नै गै होर जो गै न, साडे जवानें ते बूढ़ेएं, साडे मर्दें ते महिलाएं गी माफ़ करी देओ। ऐ अल्लाह, तुस हममें चा जेह्ड़ा बी जिʼंदा रक्खेआ, उसी इस्लाम पर जिʼंदा रक्खेआ करो ते असां चा जेह्ड़ा बी तुस मरेओ, उसी ईमान दे कारण मारी देओ।", "दाह संस्कार दी नमाज़ दे त्रिया तकबीर दे परैंत्त।", "इक मृतक वयस्क आस्तै सुन्नत दुआ।"),
        "dua_janaza_child" to DuaText("जनाज़ा प्रार्थना (बच्चा)", "हे अल्लाह, उसी साडे आस्तै इक अग्रदूत (ते मेजबान) बनाओ, उसी साडे आस्तै इक इनाम ते इक खजाना बनाओ, ते उसी साडे आस्तै इक सिफ़ारिश करने आह्ला बनाओ, जेह्दा सिफ़ारिश मंजूर कीती जंदी ऐ।", "इक ञ्याणे दी दाह संस्कार प्रार्थना च (इक कुड़ी आस्तै'इज'अलहा'आखेआ जंदा ऐ)।", "हनाफियें आसेआ सुन्ना दुआ दा अभ्यास कीता जंदा हा।"),
        "dua_mayyit_awf" to DuaText("मृतक आस्तै विस्तृत दुआ", "हे अल्लाह, उसी माफ़ करी देओ, उस पर दया करो, उसी चंगा करो ते उसी माफ़ करो। ओह्दे स्वागत गी सम्मानजनक बनाओ ते ओह्दे मकबरे गी चौड़ा करो, उसी पानी, बर्फ ते ओलों कन्नै धोओ ते उसी पापें थमां साफ करो जिʼयां इक चिट्टे कपड़े गी मैल कन्नै साफ कीता जंदा ऐ।", "दाह संस्कार दी प्रार्थना च जां मृतक आस्तै।", "अवफ इब्न मलिक (र.) दी इच्छा ही जे ओह् ओह् मृतक व्यक्ति हा।"),
        "dua_visiting_graves" to DuaText("कब्रें दा दौरा करना", "ऐ ईमान लाने आह्ले ते मुसलमान, इʼनें घरें च बस्सने आह्ले, तुसें पर शान्ति होई। जे अल्लाह चाहेगा तां असीं बी तुंʼदे कन्नै शामल होई जाईांगे। में अल्लाह कोला अपने ते तुंʼदे आस्तै कल्याण दी विनती करदा आं।", "कब्रिस्तान च दाखल होने पर।", "कब्रें दा दौरा करना मौत ते आख़िरत दी चेता दिवाउंदा ऐ।"),
        "dua_closing_eyes" to DuaText("मृतक दियां आंखें बंद करने पर", "ऐ अल्लाह, माफ़ करी देओ, मार्ग-निर्देशत लोकें च अपना दर्जा बधाओ, उंʼदे उत्तराधिकारी बनो, जेह्ड़ा ओह् छड्डदे न। हे दुनिया दे रब, सानू गी ते उʼनें गी माफ़ करी देओ, उंʼदी कबर गी चौड़ा करो ते उसी रोशनी कन्नै भरो।", "जिसलै मृतक दियां आंखें बंद करो (ओह्दे नांऽ दा जिकर करदे होई)।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अबू सलमा (र) आस्तै एह् दुआ बनाई।"),
        "dua_condolence" to DuaText("संवेदना (तज़ियाह)", "निश्चय गै जेह्ड़ा किश उʼनें लैता ओह् अल्लाह दा ऐ ते जेह्ड़ा किश उʼनें दित्ता ओह् उसी दा ऐ ते ओह्दे कोल हर चीज दी इक निश्चत अवधि ऐ, इस करियै धैर्य र'व ते इनाम दी मेद करो।", "इक दी मौत दे परैंत्त इक परोआर गी संवेदना प्रकट करना।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् संदेश अपनी धीऽ गी भेजेआ हा।"),
        "dua_placing_in_grave" to DuaText("मृतक गी कब्र च रक्खेआ जाना", "अल्लाह दे नांऽ पर ते अल्लाह दे रसूल दे रस्ते पर।", "जिसलै मृतक गी कब्र च सुट्टेआ जंदा ऐ।", "दफनाने दा सुन्नत दुआ।"),
        "dua_sneezing" to DuaText("छिक्की आना", "सारी स्तुति अल्लाह आस्तै ऐ।-अल्लाह तुंʼदे पर रहम करे।-अल्लाह तुंʼदा मार्गदर्शन करे ते तुंʼदे मामलें गी ठीक करे।", "छींकने पर श्रोता'यारहमुकल्लाह'आखदा ऐ, फ्ही जे छींकदा ऐ ओह् जवाब दिंदा ऐ।", "एह् कुसै दुए मुसलमान पर इक मुसलमान दा अधिकार ऐ।"),
        "dua_toilet_enter" to DuaText("शौचालय च दाखल होना", "अल्लाह दे नांऽ पर। ऐ अल्लाह, में अशुद्ध जिन्नें दे मरद ते जनानी शा तेरी शरण लैंदा आं।", "शौचालय च पैर रखने शा पैह्लें खब्बे पैर कन्नै जाओ।", "बिस्मिल्लाह जिन्न ते इन्सान दे बिच्च इक पर्दा बनी जंदा ऐ।"),
        "dua_toilet_exit" to DuaText("शौचालय छोड़ी दे", "(हे अल्लाह) में तुंʼदी माफी मंगदा आं।", "सज्जे पैर कन्नै शौचालय थमां बाह्र निकलदे समें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने शौचालय थमां बाह्र निकलने पर एह् आखेआ।"),
        "dua_thanking" to DuaText("कुसै दा शुक्रगुजार होना", "अल्लाह तुसें गी भले दा इनाम देवे।", "जिसलै कोई तुंʼदा कोई उपकार करदा ऐ।", "जेह्ड़ा बी एह् आखदा ऐ, उʼनें पूरी चाल्ली कन्नै आभार प्रकट कीता ऐ।"),
        "dua_love_for_allah" to DuaText("जिसलै कोई आखेआ जे'में तुसें गी अल्लाह आस्तै प्यार करदा आं'", "ओह् (अल्लाह), जिंʼदे लेई तुस मिगी प्यार करदे ओ, तुसें गी प्यार करो।", "जिसलै कोई आखेआ जे'में तुसें गी अल्लाह दी खातर प्यार करदा आं'।", "सुन्नत अल्लाह दे प्यार दा जवाब दिंदी ऐ।"),
        "dua_seeing_muslim_smile" to DuaText("नमसकार (सलाम)", "तुंʼदे पर शान्ति होई ते अल्लाह दी दया ते उंʼदी बरकतां होन।", "जिसलै कुसै मुसलमान कन्नै मिलो।", "पूरा सलाम कहने कन्नै तीस भले कर्म मिलदे न।"),
        "dua_dressing" to DuaText("कपड़े पाS", "सारी स्तुति अल्लाह आस्तै ऐ जिʼन्नै मिगी एह् वस्त्रा दित्ता ते मेरे आसेआ बगैर कुसै शक्ति जां शक्ति दे मेरे आस्तै एह् प्रदान कीता।", "जिसलै कपड़े पाई लैंदे ओ।", "पिछले पापें दी माफी दी खुश खबरी।"),
        "dua_rooster_donkey" to DuaText("मुर्गे जां गधे दी आवाज़ सुणना", "हे अल्लाह, में तुंʼदे शा तेरे बरकत (मुर्गे) दी मंग करदा आं।-में शापित (गधे) शयतान थमां अल्लाह दी शरण लैंदा आं।", "इक मुर्गे गी सुनने पर अल्लाह दा बरकत मंगो; इक गधे दे ब्रै गी सुनने पर शैतान थमां शरण लओ।", "मुर्गे गी इक दूत ते गधे गी इक शैतान दिक्खेआ जंदा ऐ।"),
        "dua_something_liked" to DuaText("किश काबले-तारीफ दिक्खेआ जाना (बुरी नज़र दे खलाफ)", "जेह्ड़ा अल्लाह ने चाहा ऐ। ऐ अल्लाह, उसी बरकत देओ।", "कुसै दी कोई काबले-तारीफ चीज दिक्खेआ जाने पर, आशीर्वाद आस्तै प्रार्थना करो।", "आशीर्वाद आस्तै प्रार्थना करना बुरी नज़र गी रोकदा ऐ।"),
        "dua_sell_buy_debt_repaid" to DuaText("जिसलै कोई कर्ज चुकाया जंदा ऐ", "अल्लाह तुसें गी तुंʼदे परोआर ते धन च आशीर्वाद देवे।", "कर्ज चुकाने आह्ले आस्तै।", "ऋण आस्तै वापसी आभार ते चुकौती ऐ।"),
        "dua_talbiyah" to DuaText("तालबिया", "में हून ऐ, हे अल्लाह, मैं हून आं। मैं हून आं, तेरा कोई साथी नेईं ऐ, मैं हून आं। निश्चत सारे स्तुति, आशीर्वाद ते प्रभुत्व तेरा ऐ। तेरा कोई साथी नेईं ऐ।", "इहराम च दाखल होने दे परैंत्त जोर-जोर कन्नै।", "हज ते उमराह दा प्रतीक।"),
        "dua_yamani_hajar" to DuaText("रुकन यमानी ते हजर असवाद दे बिच्च", "ऐ हमारे रब, असां गी इस दुनिया च चंगा ते आख़िरत च चंगा देओ, ते सानू अग्नी दी सज़ाया शा बचाओ।", "तवाफ च, यमनी कोने ते काले पत्थर दे बिच्च।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इस थाह्र पर तवाफ च एह् पढ़ा।"),
        "dua_safa_marwa" to DuaText("सफा ते मारवाह पर", "कुसै गी बी पूजा करने दा अधिकार नेईं ऐ, छड़ा अल्लाह गी, बगैर साझीदार दे। शासन उसी दा ऐ ते स्तुति उसी दी ऐ, ते हर चीज पर ओह्दे कोल अधिकार ऐ। कुसै गी बी पूजा करने दा अधिकार नेईं ऐ, छड़ा अल्लाह गी। उʼनें अपना वादा पूरा कीता, अपने दास दी मदद कीती ते अकेले संघें गी हराया।", "सफा पर चढ़ना ते किबला दा सामना करना (त्रै बारी)।", "सफा ते मारवाह पर पैगंबर सल्लल्लाह् अलीह दा फरमान।"),
        "dua_arafah" to DuaText("अराफाह दे दिन दा सभनें शा चंगा दुआ", "कुसै गी बी पूजा करने दा हक्क नेईं ऐ छड़ा अल्लाह दे, बगैर साथी दे। उसी दी बादशाहत ऐ ते उसी दी स्तुति ऐ ते ओह् हर चीज पर काबले-जिकर ऐ।", "अराफाह दा दिन-सभनें शा चंगा दुआ।", "अराफाह दे दिन दी दुआ सभनें शा शैल दुआ ऐ ते सभनें शा शैल शब्द एह् न।"),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तश़्रीक", "अल्लाह सभनें शा बड़ा ऐ, अल्लाह सभनें शा बड़ा ऐ। अल्लाह दे अलावा कोई पूज्य-प्रभु नेईं ऐ। अल्लाह सभनें शा महान ऐ, अल्लाह सभनें शा महान ऐ, ते सारी प्रशंसा अल्लाह आस्तै ऐ।", "हर इक फरजी नमाज़ दे परैंत्त 9 धुल-हिज्जा दे फजर थमां 13 धुल-हिज्जा दे असर तक्कर।", "अली ते इब्न मसूद (र. अ.) थमां रिपोर्ट कीता गेआ-हनाफियें दे मताबक वाजिब।"),
        "dua_zamzam" to DuaText("ज़मज़म पींदा ऐ", "हे अल्लाह, में तुंʼदे शा फायदेमंद ज्ञान, भरपूर प्रबंध ते हर इक रोग दा इलाज मंगदा आं।", "ज़मज़म पींदे समें, तुस जेह्ड़ा बी मनमाना ओ, ओह्दे आस्तै दुआ बनाओ।", "ज़मज़म उस चीज आस्तै ऐ जेह्दे आस्तै एह् पिया जंदा ऐ (इब्न माजाह 3062)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("सृजन पर विचार करना", "ऐ हमारे रब, तुस एह् सारा किश व्यर्थ नेईं बनाया। महिमा तुंʼदी ऐ, इस करियै असां गी अग्ग दी सज़ाया शा बचाओ।", "उʼनें लोकें दा दुआ जेह्ड़े आसमान ते धरती दी रचना पर विचार करदे न।", "समझदार लोकें दा दुआ (उलुल-अलबाब)।"),
        "dua_q_sami_na_munadiyan" to DuaText("असां विश्वास आस्तै बुलाए जाने आह्ले गी सुनाया ऐ", "ऐ हमारे रब, असां इक बुलाने आह्ले गी ईमान आस्तै पुकारदे होई सुणिआ, जेह्ड़ा आखदा ऐ,'अपने रब पर ईमान लाओ', ते असां ईमान लाया। ऐ हमारे रब, साडे पाप क्षमा करी देओ, साडे कुकर्में गी साडे शा दूर करी देओ ते सच्चें कन्नै-कन्नै सानू गी बी मारी देओ।", "धार्मकें दे बिच्च विश्वास ते मरने आस्तै इक दुआ।", "माफी ते इक चंगा अंत आस्तै दुआ।"),
        "dua_q_atina_ma_waadtana" to DuaText("तुस जेह्ड़ा वायदा कीता ऐ, ओह् सानू देओ।", "ऐ ऐ हमारे रब, अपने रसूलें दे ज़रिए जेह्ड़ा वादा कीता हा, ओह् सानू दे आस्तै मंजूर करी देओ ते क़ियामत दे दिन असां गी बदनाम नेईं करो। निश्चय गै तुस अपने वादे गी नेईं तोड़ो।", "पुनरुत्थान दे दिन अपमान शा शरण लो।", "आख़िरत च सम्मान दी तलाश करना।"),
        "dua_q_israfana" to DuaText("साʼदियां अतिरेकियां माफ करी देओ", "हे हे हमारे प्रभु, असां गी हमारे पाप ते हमारे मामलें च साडी ज्यादत गी माफ करी देओ, साडे पैर मजबूत करो ते इनकार करने आह्ले लोकें दे खलाफ साडी मदद करो।", "पैह्लें दे पैगंबरें दे साथीएं दा दुआ।", "दृढ़ता ते क्षमा आस्तै दुआ।"),
        "dua_q_jamiun_nas" to DuaText("तुस मानव जाति गी इकट्ठे करोगे", "ऐ ऐ हमारे रब, तुस निश्चत लोकें गी उस दिन इकट्ठे करोगे जेह्दे बारे च कोई शक्क नेईं ऐ। निश्चय गै अल्लाह अपने वादे गी नेईं तोड़ेगा।", "क़ियामत दे दिन निश्चत होने दी पुष्टि करना।", "उंʼदे दोआ दा द्रिढ़ता कन्नै ज्ञान च अधारत ऐ।"),
        "dua_q_maash_shahidin" to DuaText("सानू गवाहें दे बिच्च लिखो", "हे हमारे प्रभु, असां विश्वास कीता ऐ, इस करियै सानू गवाहें दे बिच्च लिखो।", "उंʼदे दी दुआ जिʼनें सच गी पहचाना ते विश्वास कीता।", "अपने विश्वास गी मंजूर करने आस्तै इक दुआ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("गलत करने आह्ले दे कन्नै नेईं", "हे हमारे प्रभु, असां गी गलत लोकें दे कन्नै नेईं लाओ।", "अल-अराफ दे लोकें दा दुआ।", "गलतें दे भाग्य शा शरण।"),
        "dua_q_tawaffana_muslimin" to DuaText("मुसलमानें दे रूपै च धैर्य ते मौत", "हे हमारे भगवान, हम पर धैर्य लाओ ते मुसलमान होने दे नाते सानू मरने देओ।", "फ़िरौन दे जादूगरें दा दुआ जिसलै ओह् विश्वास करदे हे।", "परख च धैर्य ते विश्वास पर अंत।"),
        "dua_q_la_tajalna_fitnah" to DuaText("जुल्म करने आह्ले लोकें आस्तै कोई मुक़दमा नेईं", "हम अल्लाह पर भरोसा करदे न। ऐ हमारे रब, असां गी बदमाशी करने आह्ले लोकें आस्तै अज़माइश नेईं बनाओ ते अपनी दया कन्नै असां गी इनकार करने आह्ले लोकें शा बचाओ।", "मूसा (ए. ऐस्स.) दे लोकें दा दुआ।", "ज़ुल्म ते जुल्मियें शा बचने आस्तै इक दुआ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("मुआफ़ी आस्तै नूंह (ए. ऐस्स.) दी दुआ", "ऐ मेरे रब, में तुंʼदे शा नेहा किश मंगने थमां पनाह लैंदा आं, जेह्दा मिगी कोई ज्ञान नेईं ऐ। ते जिसलै तक्कर तुस मिगी माफ नेईं करदे ते मुझ पर दया नेईं करदे, मैं घाटे च रहूंगा।", "पैगंबर नूंह (अ. स.) दे पश्चाताप दी दुआ।", "उचित तरीके कन्नै पूछने दा इक सबक।"),
        "dua_q_mudkhala_sidq" to DuaText("सत्य दा प्रवेश ते निकास", "हे मेरे प्रभु, मिगी सत्य दे कन्नै दाखल होने ते सत्य दे कन्नै नस्सने आस्तै, ते मिगी अपनी बक्खी थमां इक मददगार अधिकार प्रदान करो।", "कुसै नमें कम्म च दाखल होने शा पैह्लें, घर जां थाह्र।", "दुआ ने हिजरे दे समें पैगंबर सल्लल्लाह् अलैहि वसल्लम गी सिखाया हा।"),
        "dua_q_la_tadharni_fardan" to DuaText("ज़कारिया दी दुआ (ए. ऐस्स.)-मिगी इकलै नेईं छडो", "हे मेरे प्रभु, मिगी इकलै नेईं छडो ते तुस सभनें शा अच्छे उत्तराधिकारी ओ।", "ञ्याणें दी तलाश करने आह्ले लोकें आस्तै।", "इस दुआ दे राहें अल्लाह ने याह्या (ए. ऐस्स.) प्रदान कीती।"),
        "dua_q_munzalan_mubarakan" to DuaText("इक बरकत आह्ली लैंडिंग थाह्र", "मेरे प्रभु, मिगी इक बरकत आह्ली लैंडिंग थाह्र पर उतरने देओ, ते तुस धरती पर लाने आह्ले लोकें च सभनें शा शैल ओ।", "जिसलै कुसै नमें घर च जाई जां कुसै थाह्र पर रुको-नूंह (ए. ऐस्स.) दी दुआ।", "नमीं थाह्र पर आशीर्वाद आस्तै दुआ।"),
        "dua_q_amanna_faghfir" to DuaText("असां विश्वास कीता ऐ, इस करियै सानू माफ करी देओ।", "ऐ हमारे रब, असां ईमान लाया ऐ, इस करियै असां गी माफ करी देओ ते साडे पर रहम करो, ते तुस सभनें शा बड़े दयावान ओ।", "अल्लाह दे नेक सेवकें दी दुआ।", "माफी ते दया आस्तै इक व्यापक दुआ।"),
        "dua_q_isrif_jahannam" to DuaText("नर्क दी सʼजा गी टाल देओ", "ऐ हमारे रब, हमसे नर्क दी सज़ाया तोड़ो, वाक़ई एह्दे सज़ाया च लगातार कमी होंदी ऐ। वाक़ई, एह् इक बदतमीजी दी बस्ती ते नवास ऐ।", "परम दयावान (इबादत-अर-रहमान) दे सेवकें दी दुआ।", "नरक थमां पनाह आस्तै इक कुरान दी दुआ।"),
        "dua_q_hab_li_hukman" to DuaText("इब्राहिम (ए. ऐस्स.) दा दुआ-बुद्धि ते जन्नत", "हे मेरे प्रभु, मिगी बुद्धि देओ ते सच्चें कन्नै मेरे कन्नै शामल होवो, बाद दियें पीढ़ियें च मेरा सम्मानजनक जिकर करो, ते मिगी आनंद दे बगीचे दे वारसें च शामल करो।", "बुद्धि दी मंग करना, धार्मक ते परादीस दी संगति।", "इब्राहिम (ए. ऐस्स.) दी इक व्यापक दुआ।"),
    )
}
